import{_ as a,o as t,c as r,a4 as o,ao as s}from"./chunks/framework.CmuCl-jw.js";const u=JSON.parse('{"title":"External Storages","description":"","frontmatter":{},"headers":[],"relativePath":"apps/data/external-storages.md","filePath":"apps/data/external-storages.md"}'),n={name:"apps/data/external-storages.md"};function i(l,e,c,d,p,g){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="external-storages" tabindex="-1">External Storages <a class="header-anchor" href="#external-storages" aria-label="Permalink to “External Storages”">​</a></h1><p><strong>External Storages</strong> are existing data storages you already own — as an individual astronomer or as an organisation running Arcsecond.local. You attach them to your install so their content is indexed alongside the data Arcsecond.local holds itself. There is no limit on the number of storages you can attach.</p><p>Attached storages are <strong>read-only</strong>: Arcsecond.local never modifies anything in them. Credentials are provided once, then stored encrypted and securely sealed (read more in <a href="./credentials-security">Credentials &amp; Security</a>).</p><p>Find tutorials on how to provide credentials for your external storages in:</p><ul><li><a href="./external-storage-aws">Amazon AWS S3 buckets</a></li><li><a href="./external-storage-dropbox">Dropbox</a></li><li><a href="./external-storage-localdisk">Local disk</a></li><li><a href="./external-storage-ftp">FTP</a></li><li><a href="./external-storage-sftp">SFTP</a></li><li><a href="./external-storage-azure">Azure</a> (<code>in preparation</code>)</li><li><a href="./external-storage-archives">Archives</a> (ESO, CADC, HST, etc — <code>in preparation</code>)</li></ul><p>Based on the storages it can reach, Arcsecond.local extracts and organises information about your nights and observed targets.</p><p><img src="'+s+'" alt="Overview of Observations &amp; Data" data-zoomable=""></p><p>Arcsecond.local scans and parses the content of external storages, exactly as it does for the data <a href="./storage">stored on the install itself</a>. This parsing lets it:</p><ul><li>extract FITS- and XISF-file headers, for easy searching in the web interface,</li><li>create 2D-image and 1D-spectrum previews,</li><li><strong>build your personal list of all your follow-up targets, associated with their data</strong> — combining everything the install holds and every external storage you have attached,</li><li>reconstruct your observing nights (when possible).</li></ul><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>We are working on an option to restrict the parsing to specific (sub)folder(s).</p></div>',10)])])}const f=a(n,[["render",i]]);export{u as __pageData,f as default};
